CREATE TYPE session_status AS ENUM ('LIVE','ENDED','PAUSED');
CREATE TYPE entitlement_status AS ENUM ('CREATED','AWAITING_QUESTION','MODERATION','QUEUED','FULFILLING','COMPLETED','NEEDS_REPLACEMENT','MANUAL_REVIEW','CANCELLED');
CREATE TYPE request_status AS ENUM ('RECEIVED','MODERATION','CARD_SELECTION','GENERATING_TEXT','VALIDATING_TEXT','GENERATING_AUDIO','READY','PLAYING','COMPLETED','FAILED_RETRYABLE','MANUAL_REVIEW');
CREATE TABLE IF NOT EXISTS live_sessions (id uuid PRIMARY KEY, account_key text NOT NULL, locale text NOT NULL, status session_status NOT NULL, started_at timestamptz NOT NULL, ended_at timestamptz);
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, platform text NOT NULL, platform_user_id text NOT NULL, username text NOT NULL, display_name text NOT NULL, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, CONSTRAINT users_platform_platform_user_id_unique UNIQUE(platform, platform_user_id));
CREATE TABLE IF NOT EXISTS raw_events (id uuid PRIMARY KEY, session_id uuid NOT NULL, source text NOT NULL, external_id text NOT NULL, type text NOT NULL, payload_json jsonb NOT NULL, occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT raw_events_source_external_id_unique UNIQUE(source, external_id));
CREATE TABLE IF NOT EXISTS comments (id uuid PRIMARY KEY, raw_event_id uuid NOT NULL, session_id uuid NOT NULL, user_id uuid NOT NULL, text text NOT NULL, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gift_products (id uuid PRIMARY KEY, account_key text NOT NULL, gift_id text NOT NULL, product_code text NOT NULL, cards integer NOT NULL, priority integer NOT NULL, question_required boolean NOT NULL, max_words integer NOT NULL, max_audio_seconds integer NOT NULL, enabled boolean NOT NULL);
CREATE TABLE IF NOT EXISTS gift_events (id uuid PRIMARY KEY, raw_event_id uuid NOT NULL UNIQUE, session_id uuid NOT NULL, user_id uuid NOT NULL, gift_id text NOT NULL, quantity integer NOT NULL, product_id uuid, finalized_at timestamptz);
CREATE TABLE IF NOT EXISTS entitlements (id uuid PRIMARY KEY, gift_event_id uuid NOT NULL UNIQUE, user_id uuid NOT NULL, product_id uuid NOT NULL, status entitlement_status NOT NULL, question_deadline timestamptz, failure_reason text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS reading_requests (id uuid PRIMARY KEY, entitlement_id uuid UNIQUE, session_id uuid NOT NULL, user_id uuid NOT NULL, display_name text NOT NULL, source text NOT NULL, question text, status request_status NOT NULL, priority integer NOT NULL, queued_at timestamptz NOT NULL, started_at timestamptz, completed_at timestamptz);
CREATE TABLE IF NOT EXISTS selected_cards (request_id uuid NOT NULL, position integer NOT NULL, card_id text NOT NULL, orientation text NOT NULL, seed_hash text NOT NULL, UNIQUE(request_id, position));
CREATE TABLE IF NOT EXISTS readings (id uuid PRIMARY KEY, request_id uuid NOT NULL, locale text NOT NULL, generated_json jsonb NOT NULL, spoken_text text NOT NULL, safety_status text NOT NULL, generator_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audio_assets (id uuid PRIMARY KEY, reading_id uuid NOT NULL, provider text NOT NULL, voice text NOT NULL, content_hash text NOT NULL UNIQUE, local_path text NOT NULL, duration_ms integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS playback_attempts (id uuid PRIMARY KEY, request_id uuid NOT NULL, command_id uuid NOT NULL, status text NOT NULL, started_at timestamptz, last_heartbeat_at timestamptz, completed_at timestamptz, error text);
CREATE TABLE IF NOT EXISTS operator_actions (id uuid PRIMARY KEY, action text NOT NULL, request_id uuid, detail_json jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox (id uuid PRIMARY KEY, topic text NOT NULL, aggregate_id uuid NOT NULL, payload_json jsonb NOT NULL, available_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0, last_error text);
CREATE TABLE IF NOT EXISTS system_events (id uuid PRIMARY KEY, type text NOT NULL, payload_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
